1	import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
2	import axios from 'axios';
3	import Sidebar from '../components/Sidebar';
4	import '../css/Dashboard.css';
5	import '../css/Management.css';
6	import '../css/Users.css';
7	import '../css/IncidentDashboard.css';
8	
9	// ---------------------------------------------------------------------------
10	// Badge helpers
11	// ---------------------------------------------------------------------------
12	const severityClass = (s) => {
13	  switch (s) {
14	    case 'Critical': return 'inc-badge inc-severity-critical';
15	    case 'High':     return 'inc-badge inc-severity-high';
16	    case 'Medium':   return 'inc-badge inc-severity-medium';
17	    case 'Low':      return 'inc-badge inc-severity-low';
18	    default:         return 'inc-badge';
19	  }
20	};
21	
22	const statusClass = (s) => {
23	  switch (s) {
24	    case 'Active':                return 'inc-badge inc-status-active';
25	    case 'Investigating':         return 'inc-badge inc-status-investigating';
26	    case 'Escalated to Security': return 'inc-badge inc-status-escalated';
27	    case 'Cleared':               return 'inc-badge inc-status-cleared';
28	    default:                      return 'inc-badge';
29	  }
30	};
31	
32	const sourceClass = (s) => {
33	  switch (s) {
34	    case 'Facial Recognition': return 'inc-badge inc-source-fr';
35	    case 'Manual':             return 'inc-badge inc-source-manual';
36	    default:                   return 'inc-badge inc-source-od';
37	  }
38	};
39	
40	const sourceLabel = (s) => {
41	  switch (s) {
42	    case 'Facial Recognition': return 'Face ID';
43	    case 'Manual':             return 'Manual';
44	    default:                   return 'Object Det.';
45	  }
46	};
47	
48	const truncate = (str, n = 30) =>
49	  str && str.length > n ? str.slice(0, n) + '…' : str;
50	
51	// Break a location string into lines: max 2 words OR max 12 chars per line,
52	// whichever limit is hit first. Total display capped at 30 chars (word boundary).
53	const formatLocation = (str) => {
54	  if (!str) return '';
55	  let text = str;
56	  let ellipsis = false;
57	  if (str.length > 30) {
58	    const cut = str.slice(0, 30);
59	    const lastSpace = cut.lastIndexOf(' ');
60	    text = lastSpace > 0 ? cut.slice(0, lastSpace) : cut;
61	    ellipsis = true;
62	  }
63	  const words = text.split(/\s+/).filter(Boolean);
64	  const lines = [];
65	  let lineWords = [];
66	  let lineLen = 0;
67	  for (const word of words) {
68	    if (lineWords.length === 0) {
69	      lineWords = [word];
70	      lineLen = word.length;
71	    } else {
72	      const tentativeLen = lineLen + 1 + word.length;
73	      if (tentativeLen > 15) {
74	        lines.push(lineWords.join(' '));
75	        lineWords = [word];
76	        lineLen = word.length;
77	      } else {
78	        lineWords.push(word);
79	        lineLen = tentativeLen;
80	      }
81	    }
82	  }
83	  if (lineWords.length > 0) lines.push(lineWords.join(' '));
84	  if (ellipsis && lines.length > 0) lines[lines.length - 1] += '…';
85	  return lines.join('\n');
86	};
87	
88	// ---------------------------------------------------------------------------
89	// Component
90	// ---------------------------------------------------------------------------
91	const IncidentDashboard = () => {
92	  // --- Data ---
93	  const [incidents, setIncidents]   = useState([]);
94	  const [loading, setLoading]       = useState(true);
95	  const [newRowIds, setNewRowIds]   = useState(new Set());
96	  const [deletingId, setDeletingId] = useState(null);
97	
98	  // --- Filters ---
99	  const [search, setSearch]                 = useState('');
100	  const [severityFilter, setSeverityFilter] = useState('All');
101	  const [sourceFilter, setSourceFilter]     = useState('All');
102	  const [statusFilter, setStatusFilter]     = useState('All');
103	
104	  // --- Detail / edit modal ---
105	  const [selectedIncident, setSelectedIncident] = useState(null);
106	  const [editMode, setEditMode]                 = useState(false);
107	  const [editForm, setEditForm]                 = useState({ resolutionStatus: '', notes: '' });
108	  const [editSaving, setEditSaving]             = useState(false);
109	
110	  // --- Create modal ---
111	  const [showCreate, setShowCreate]     = useState(false);
112	  const [createForm, setCreateForm]     = useState({
113	    camera_location: '',
114	    status: 'UNAUTHORIZED_ACCESS',
115	    severity: 'Medium',
116	    person_name: '',
117	    confidence_score: '',
118	    notes: '',
119	  });
120	  const [createSaving, setCreateSaving] = useState(false);
121	
122	  // --- Delete confirm modal ---
123	  const [deleteTarget, setDeleteTarget] = useState(null);
124	  const [deleteSaving, setDeleteSaving] = useState(false);
125	
126	  // --- Toast stack (array, each has its own 3s timer) ---
127	  const [toasts, setToasts]     = useState([]);
128	  const toastCounterRef         = useRef(0);
129	
130	  // --- Back to top ---
131	  const [showBackTop, setShowBackTop] = useState(false);
132	  const [backTopLeft, setBackTopLeft] = useState('50%');
133	  const mainRef = useRef(null);
134	
135	  // ---------------------------------------------------------------------------
136	  // Toast (stacking, non-overwriting, typed)
137	  // ---------------------------------------------------------------------------
138	  const showToast = useCallback((msg, type = 'success') => {
139	    const id = ++toastCounterRef.current;
140	    setToasts(prev => [...prev, { id, message: msg, type, removing: false }]);
141	    // After 3s start exit animation, then remove from DOM after animation
142	    setTimeout(() => {
143	      setToasts(prev => prev.map(t => t.id === id ? { ...t, removing: true } : t));
144	      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 400);
145	    }, 3000);
146	  }, []);
147	
148	  const getToken = () => localStorage.getItem('accessToken');
149	
150	  // ---------------------------------------------------------------------------
151	  // Back-to-top: scroll listener on dashboard-main (it owns overflow-y: auto)
152	  // ---------------------------------------------------------------------------
153	  useEffect(() => {
154	    const el = mainRef.current;
155	    if (!el) return;
156	    const handleScroll = () => setShowBackTop(el.scrollTop > 300);
157	    el.addEventListener('scroll', handleScroll, { passive: true });
158	    return () => el.removeEventListener('scroll', handleScroll);
159	  }, []);
160	
161	  // Track dashboard-main position for accurate horizontal centering
162	  useEffect(() => {
163	    const updatePos = () => {
164	      if (mainRef.current) {
165	        const rect = mainRef.current.getBoundingClientRect();
166	        setBackTopLeft(`${rect.left + rect.width / 2}px`);
167	      }
168	    };
169	    updatePos();
170	    window.addEventListener('resize', updatePos);
171	    return () => window.removeEventListener('resize', updatePos);
172	  }, []);
173	
174	  // ---------------------------------------------------------------------------
175	  // Fetch from API
176	  // ---------------------------------------------------------------------------
177	  const fetchIncidents = useCallback(async (silent = false) => {
178	    if (!silent) setLoading(true);
179	    try {
180	      const res = await axios.get('/api/incident', {
181	        headers: { Authorization: `Bearer ${getToken()}` },
182	      });
183	      setIncidents(Array.isArray(res.data) ? res.data : []);
184	    } catch (err) {
185	      console.error('Failed to fetch incidents:', err);
186	      if (!silent) showToast('Failed to load incidents from server.', 'error');
187	    } finally {
188	      if (!silent) setLoading(false);
189	    }
190	  }, [showToast]);
191	
192	  // ---------------------------------------------------------------------------
193	  // Background poll — every 10s, silently diff for new AI-created incidents
194	  // Uses functional updater so prev is always current state (no stale closure)
195	  // ---------------------------------------------------------------------------
196	  const pollForNewIncidents = useCallback(async () => {
197	    try {
198	      const res = await axios.get('/api/incident', {
199	        headers: { Authorization: `Bearer ${getToken()}` },
200	      });
201	      const freshData = Array.isArray(res.data) ? res.data : [];
202	
203	      setIncidents(prev => {
204	        const existingIds = new Set(prev.map(i => i.id));
205	        const brandNew = freshData.filter(i => !existingIds.has(i.id));
206	
207	        if (brandNew.length === 0) return prev; // no change — skip re-render
208	
209	        const newIdSet = new Set(brandNew.map(i => i.id));
210	        setNewRowIds(cur => new Set([...cur, ...newIdSet]));
211	        setTimeout(() => {
212	          setNewRowIds(cur => {
213	            const n = new Set(cur);
214	            newIdSet.forEach(id => n.delete(id));
215	            return n;
216	          });
217	        }, 700);
218	
219	        return freshData;
220	      });
221	    } catch {
222	      // silent — polling errors are not surfaced to the user
223	    }
224	  }, []); // intentionally empty: functional updater pattern avoids stale closures
225	
226	  // ---------------------------------------------------------------------------
227	  // On mount: fetch from DB (no seed — live AI data only)
228	  // ---------------------------------------------------------------------------
229	  useEffect(() => {
230	    fetchIncidents();
231	  }, [fetchIncidents]);
232	
233	  // ---------------------------------------------------------------------------
234	  // Polling effect — 10s interval, cleaned up on unmount
235	  // ---------------------------------------------------------------------------
236	  useEffect(() => {
237	    const id = setInterval(pollForNewIncidents, 10_000);
238	    return () => clearInterval(id);
239	  }, [pollForNewIncidents]);
240	
241	  // ---------------------------------------------------------------------------
242	  // Filter + stats
243	  // ---------------------------------------------------------------------------
244	  const filtered = useMemo(() => {
245	    const q = search.toLowerCase();
246	    return incidents.filter((i) => {
247	      const matchSearch =
248	        !q ||
249	        (i.person_name || '').toLowerCase().includes(q) ||
250	        i.camera_location.toLowerCase().includes(q);
251	      const matchSeverity = severityFilter === 'All' || i.severity === severityFilter;
252	      const matchSource   = sourceFilter   === 'All' || i.source === sourceFilter;
253	      const matchStatus   = statusFilter   === 'All' || i.resolutionStatus === statusFilter;
254	      return matchSearch && matchSeverity && matchSource && matchStatus;
255	    });
256	  }, [incidents, search, severityFilter, sourceFilter, statusFilter]);
257	
258	  const sourceCounts = useMemo(() => ({
259	    ai:     incidents.filter(i => i.source !== 'Manual').length,
260	    manual: incidents.filter(i => i.source === 'Manual').length,
261	  }), [incidents]);
262	
263	  const stats = useMemo(() => ({
264	    total:         filtered.length,
265	    critical:      filtered.filter((i) => i.severity === 'Critical' && i.resolutionStatus === 'Active').length,
266	    investigating: filtered.filter((i) => ['Investigating', 'Escalated to Security'].includes(i.resolutionStatus)).length,
267	    cleared:       filtered.filter((i) => i.resolutionStatus === 'Cleared').length,
268	  }), [filtered]);
269	
270	  // ---------------------------------------------------------------------------
271	  // Handlers
272	  // ---------------------------------------------------------------------------
273	  const openDetail = (incident) => {
274	    setSelectedIncident(incident);
275	    setEditMode(false);
276	    setEditForm({
277	      resolutionStatus: incident.resolutionStatus || 'Active',
278	      notes: incident.notes || '',
279	    });
280	  };
281	
282	  const closeDetail = () => {
283	    setSelectedIncident(null);
284	    setEditMode(false);
285	  };
286	
287	  const handleDelete = (incident) => setDeleteTarget(incident);
288	
289	  const confirmDelete = async () => {
290	    const targetId       = deleteTarget.id;
291	    const targetLocation = deleteTarget.camera_location;
292	    setDeleteTarget(null);  // close confirm modal right away
293	    setDeleteSaving(true);
294	    try {
295	      await axios.delete(`/api/incident/${targetId}`, {
296	        headers: { Authorization: `Bearer ${getToken()}` },
297	      });
298	      if (selectedIncident?.id === targetId) closeDetail();
299	      // Play exit animation then remove from state
300	      setDeletingId(targetId);
301	      setTimeout(() => {
302	        setIncidents(prev => prev.filter(i => i.id !== targetId));
303	        setDeletingId(null);
304	      }, 400);
305	      showToast(`Incident #${targetId} at ${targetLocation} deleted.`, 'delete');
306	    } catch (err) {
307	      console.error('Delete failed:', err);
308	      showToast('Failed to delete incident. Please try again.', 'error');
309	    } finally {
310	      setDeleteSaving(false);
311	    }
312	  };
313	
314	  const handleCreate = async (e) => {
315	    e.preventDefault();
316	    setCreateSaving(true);
317	    try {
318	      const res = await axios.post('/api/incident', {
319	        camera_location: createForm.camera_location,
320	        status: createForm.status,
321	        source: 'Manual',
322	        severity: createForm.severity,
323	        person_name: createForm.person_name || undefined,
324	        confidence_score: createForm.confidence_score
325	          ? parseFloat(createForm.confidence_score)
326	          : undefined,
327	        notes: createForm.notes || '',
328	      }, { headers: { Authorization: `Bearer ${getToken()}` } });
329	
330	      setIncidents(prev => [res.data, ...prev]);
331	      setNewRowIds(prev => new Set([...prev, res.data.id]));
332	      setTimeout(() => {
333	        setNewRowIds(prev => { const n = new Set(prev); n.delete(res.data.id); return n; });
334	      }, 700);
335	
336	      setShowCreate(false);
337	      setCreateForm({
338	        camera_location: '',
339	        status: 'UNAUTHORIZED_ACCESS',
340	        severity: 'Medium',
341	        person_name: '',
342	        confidence_score: '',
343	        notes: '',
344	      });
345	      showToast('Incident logged successfully.', 'success');
346	    } catch (err) {
347	      console.error('Create failed:', err);
348	      showToast('Failed to create incident. Please check required fields.', 'error');
349	    } finally {
350	      setCreateSaving(false);
351	    }
352	  };
353	
354	  const handleSaveEdit = async () => {
355	    setEditSaving(true);
356	    try {
357	      const res = await axios.patch(`/api/incident/${selectedIncident.id}`, editForm, {
358	        headers: { Authorization: `Bearer ${getToken()}` },
359	      });
360	      setIncidents(prev => prev.map(i => i.id === selectedIncident.id ? res.data : i));
361	      setSelectedIncident(res.data);
362	      setEditMode(false);
363	      showToast('Incident updated.', 'success');
364	    } catch (err) {
365	      console.error('Update failed:', err);
366	      showToast('Failed to save changes. Please try again.', 'error');
367	    } finally {
368	      setEditSaving(false);
369	    }
370	  };
371	
372	  // ---------------------------------------------------------------------------
373	  // Render
374	  // ---------------------------------------------------------------------------
375	  return (
376	    <div className="dashboard-layout">
377	      <Sidebar />
378	
379	      <main className="dashboard-main" ref={mainRef}>
380	        {/* ---- Header ---- */}
381	        <header className="dashboard-header">
382	          <div className="header-titles">
383	            <h1>Incident Command Center</h1>
384	            <p style={{ color: '#94a3b8', marginTop: '4px' }}>
385	              AI-generated and manually logged security incidents
386	            </p>
387	          </div>
388	          <button className="inc-create-btn" onClick={() => setShowCreate(true)}>
389	            + Log Incident
390	          </button>
391	        </header>
392	
393	        {/* ---- Summary Cards ---- */}
394	        <div className="inc-stats-grid">
395	          <div className="inc-stat-card inc-stat-blue">
396	            <div className="inc-stat-value">{stats.total}</div>
397	            <div className="inc-stat-label">Total Incidents</div>
398	          </div>
399	          <div className="inc-stat-card inc-stat-red">
400	            <div className="inc-stat-value">{stats.critical}</div>
401	            <div className="inc-stat-label">Critical / Active</div>
402	          </div>
403	          <div className="inc-stat-card inc-stat-orange">
404	            <div className="inc-stat-value">{stats.investigating}</div>
405	            <div className="inc-stat-label">Under Investigation</div>
406	          </div>
407	          <div className="inc-stat-card inc-stat-green">
408	            <div className="inc-stat-value">{stats.cleared}</div>
409	            <div className="inc-stat-label">Cleared</div>
410	          </div>
411	        </div>
412	
413	        {/* ---- Source Counter ---- */}
414	        <div className="inc-source-counter">
415	          <span className="inc-source-chip inc-source-chip-ai">AI Detected: {sourceCounts.ai}</span>
416	          <span className="inc-source-chip-divider">|</span>
417	          <span className="inc-source-chip inc-source-chip-manual">Manually Logged: {sourceCounts.manual}</span>
418	        </div>
419	
420	        {/* ---- Loading bar ---- */}
421	        {loading && <div className="inc-loading-bar">Loading incidents...</div>}
422	
423	        {/* ---- Filter Bar ---- */}
424	        <div className="inc-filter-bar">
425	          <input
426	            type="text"
427	            className="inc-search-input"
428	            placeholder="Search by person or location..."
429	            value={search}
430	            onChange={(e) => setSearch(e.target.value)}
431	          />
432	          <select
433	            className="inc-select"
434	            value={severityFilter}
435	            onChange={(e) => setSeverityFilter(e.target.value)}
436	            aria-label="Filter by severity"
437	          >
438	            <option value="All">All Severities</option>
439	            <option>Critical</option>
440	            <option>High</option>
441	            <option>Medium</option>
442	            <option>Low</option>
443	          </select>
444	          <select
445	            className="inc-select"
446	            value={sourceFilter}
447	            onChange={(e) => setSourceFilter(e.target.value)}
448	            aria-label="Filter by source"
449	          >
450	            <option value="All">All Sources</option>
451	            <option>Facial Recognition</option>
452	            <option>Object Detection</option>
453	            <option value="Manual">Manual</option>
454	          </select>
455	          <select
456	            className="inc-select"
457	            value={statusFilter}
458	            onChange={(e) => setStatusFilter(e.target.value)}
459	            aria-label="Filter by resolution status"
460	          >
461	            <option value="All">All Statuses</option>
462	            <option>Active</option>
463	            <option>Investigating</option>
464	            <option>Escalated to Security</option>
465	            <option>Cleared</option>
466	          </select>
467	        </div>
468	
469	        {/* ---- Toast Stack (between filter bar and table) ---- */}
470	        {toasts.length > 0 && (
471	          <div className="inc-toast-stack">
472	            {toasts.map(t => (
473	              <div
474	                key={t.id}
475	                className={`inc-toast-item inc-toast-${t.type}${t.removing ? ' removing' : ''}`}
476	              >
477	                {t.message}
478	              </div>
479	            ))}
480	          </div>
481	        )}
482	
483	        {/* ---- Incidents Table ---- */}
484	        <div className="table-container">
485	          <table className="management-table">
486	            <thead>
487	              <tr>
488	                <th>TIMESTAMP</th>
489	                <th>LOCATION</th>
490	                <th>PERSON</th>
491	                <th>SOURCE</th>
492	                <th>CONFIDENCE</th>
493	                <th>SEVERITY</th>
494	                <th>STATUS</th>
495	                <th style={{ textAlign: 'center' }}>ACTIONS</th>
496	              </tr>
497	            </thead>
498	            <tbody>
499	              {!loading && filtered.length === 0 ? (
500	                <tr>
501	                  <td colSpan="8" style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
502	                    No incidents match the current filters.
503	                  </td>
504	                </tr>
505	              ) : (
506	                filtered.map((incident) => {
507	                  const rowClass = [
508	                    newRowIds.has(incident.id)   ? 'inc-row-new'      : '',
509	                    incident.id === deletingId   ? 'inc-row-deleting' : '',
510	                    incident.source === 'Manual' ? 'inc-row-manual'   : '',
511	                  ].filter(Boolean).join(' ');
512	
513	                  return (
514	                    <tr key={incident.id} className={rowClass || undefined}>
515	                      <td style={{ fontFamily: 'monospace', color: '#cbd5e1', fontSize: '0.83rem' }}>
516	                        {new Date(incident.createdAt).toLocaleString('en-SG')}
517	                      </td>
518	                      <td style={{ color: '#e2e8f0' }} title={incident.camera_location}>
519	                        <span style={{ whiteSpace: 'pre-line', lineHeight: '1.45', overflowWrap: 'anywhere', wordBreak: 'break-all' }}>
520	                          {formatLocation(incident.camera_location)}
521	                        </span>
522	                      </td>
523	                      <td>
524	                        {incident.person_name ? (
525	                          <div className="inc-person-cell" title={incident.person_name}>
526	                            <div className="inc-person-initial">
527	                              {incident.person_name[0].toUpperCase()}
528	                            </div>
529	                            <span>{truncate(incident.person_name)}</span>
530	                          </div>
531	                        ) : (
532	                          <em style={{ color: '#64748b' }}>Unknown</em>
533	                        )}
534	                      </td>
535	                      <td>
536	                        <span className={sourceClass(incident.source)}>
537	                          {sourceLabel(incident.source)}
538	                        </span>
539	                      </td>
540	                      <td style={{ fontFamily: 'monospace', color: '#94a3b8' }}>
541	                        {incident.confidence_score != null
542	                          ? `${(incident.confidence_score * 100).toFixed(1)}%`
543	                          : <em style={{ color: '#475569' }}>—</em>}
544	                      </td>
545	                      <td>
546	                        <span className={severityClass(incident.severity)}>
547	                          {incident.severity}
548	                        </span>
549	                      </td>
550	                      <td>
551	                        <span className={statusClass(incident.resolutionStatus)}>
552	                          {incident.resolutionStatus}
553	                        </span>
554	                      </td>
555	                      <td className="actions-cell">
556	                        <div className="action-button-group">
557	                          <button
558	                            className="action-btn action-neutral"
559	                            onClick={() => openDetail(incident)}
560	                          >
561	                            View
562	                          </button>
563	                          <button
564	                            className="action-btn action-danger"
565	                            onClick={() => handleDelete(incident)}
566	                          >
567	                            Delete
568	                          </button>
569	                        </div>
570	                      </td>
571	                    </tr>
572	                  );
573	                })
574	              )}
575	            </tbody>
576	          </table>
577	        </div>
578	
579	        {/* ---- Detail / Edit Modal ---- */}
580	        {selectedIncident && (
581	          <div className="modal-overlay" onClick={closeDetail}>
582	            <div className="inc-detail-modal" onClick={(e) => e.stopPropagation()}>
583	              <div className="inc-modal-header">
584	                <div>
585	                  <h2>Incident Report</h2>
586	                  <p style={{ color: '#64748b', margin: 0, fontSize: '0.85rem' }}>
587	                    ID #{selectedIncident.id}
588	                  </p>
589	                </div>
590	                <div style={{ display: 'flex', gap: '8px' }}>
591	                  {editMode ? (
592	                    <button className="edit-btn" onClick={() => setEditMode(false)}>
593	                      Cancel
594	                    </button>
595	                  ) : (
596	                    <button
597	                      className="edit-btn"
598	                      onClick={() => {
599	                        setEditMode(true);
600	                        setEditForm({
601	                          resolutionStatus: selectedIncident.resolutionStatus || 'Active',
602	                          notes: selectedIncident.notes || '',
603	                        });
604	                      }}
605	                    >
606	                      Edit
607	                    </button>
608	                  )}
609	                  <button className="edit-btn" onClick={closeDetail}>
610	                    ✕ Close
611	                  </button>
612	                </div>
613	              </div>
